import unreal_engine as ue
from unreal_engine.classes import Blueprint

def safe_name(o):
    try: return o.get_name()
    except Exception: return str(o)

def safe_class(o):
    try: return o.get_class().get_name()
    except Exception: return str(type(o))

def read_props(obj, keywords=None, limit=200):
    d = {'name': safe_name(obj), 'class': safe_class(obj)}
    try:
        props = obj.properties()
        if keywords:
            props = [p for p in props if any(k in p.lower() for k in keywords)]
        d['props'] = props[:limit]
        vals = {}
        for p in props[:limit]:
            try:
                vals[p] = str(getattr(obj, p))
            except Exception as e:
                vals[p] = 'ERR ' + str(e)
        d['values'] = vals
    except Exception as e:
        d['error'] = str(e)
    return d

