cdo = boss.GeneratedClass.get_cdo()
out = {}
cap = cdo.CapsuleComponent
out['capsule_filtered'] = read_props(cap, ['capsule','radius','half','scale','collision','overlap','profile','response','extent','relative','absolute'])
# Try direct common accessors/properties
common = ['CapsuleRadius','CapsuleHalfHeight','ShapeScale','RelativeScale3D','RelativeLocation','RelativeRotation','CollisionProfileName','CollisionEnabled','CollisionObjectType','CollisionResponses','bGenerateOverlapEvents','bHiddenInGame']
vals = {}
for p in common:
    try: vals[p] = str(getattr(cap, p))
    except Exception as e: vals[p] = 'ERR ' + str(e)
out['capsule_common'] = vals
# component templates names/classes
try:
    out['component_templates'] = [{'name': safe_name(t), 'class': safe_class(t)} for t in boss.ComponentTemplates]
except Exception as e:
    out['component_templates_error'] = str(e)

