        elif isinstance(v, dict):
            inspected.append({'attr': attr+'_keys', 'keys': [str(k) for k in list(v.keys())[:50]]})
            for i, (k, item) in enumerate(list(v.items())[:20]):
                inspected.append({'attr': attr+'[%s]'%str(k), 'object': read_props(item, ['task','event','damage','attack','range','radius','target','collision','duration','delay','offset','montage','tag','class'], 120)})
        else:
            inspected.append({'attr': attr+'_obj', 'object': read_props(v, ['node','task','event','damage','attack','range','radius','target','collision','duration','delay','offset','montage','tag','class'], 120)})
    except Exception as e:
        inspected.append({'attr': attr+'_inspect_error', 'error': str(e)})
out['skill_inspected'] = inspected
