    except Exception: return str(o)

def safe_class(o):
    try: return o.get_class().get_name()
    except Exception: return str(type(o))

def props_values(obj, limit=200):
    info={'name':safe_name(obj),'class':safe_class(obj)}
    try:
        props=obj.properties()
        info['props']=props[:limit]
        vals={}
        for p in props[:limit]:
            try:
                v=getattr(obj,p)
                vals[p]=str(v)
