graph=cdo.PESkillEdGraph
out={'graph':props_values(graph)}
try:
    nodes=graph.Nodes
    out['node_count']=len(nodes)
    node_infos=[]
    for i,n in enumerate(nodes):
        ni=props_values(n)
        # inspect direct UObject/list/dict fields one level deeper for task/node data
        deep=[]
        try:
            for p in n.properties():
                try: v=getattr(n,p)
                except Exception: continue
                if hasattr(v,'properties'):
                    deep.append({'field':p,'object':props_values(v,120)})
                elif isinstance(v,list):
                    arr=[]
                    for j,item in enumerate(v[:10]):
                        if hasattr(item,'properties'):
                            arr.append({'index':j,'object':props_values(item,120)})
                        else:
                            arr.append({'index':j,'value':str(item)})
                    if arr: deep.append({'field':p,'list':arr})
                elif isinstance(v,dict):
                    deep.append({'field':p,'dict_keys':[str(k) for k in list(v.keys())[:20]], 'dict_values':[str(x) for x in list(v.values())[:20]]})
        except Exception as e:
            deep.append({'error':str(e)})
        ni['deep']=deep
        node_infos.append(ni)
    out['nodes']=node_infos
except Exception as e:
    out['nodes_error']=str(e)
